/* ==========================================================================
   Hazardous Substances (specification module 13)
   - Register: name, manufacturer, supplier, branch, storage location,
     quantity, hazard classification (pictograms), the safety data sheet
     (linked from the Document Manager or uploaded) with its date and review
     date, required PPE, handling and storage controls, exposure monitoring,
     the risk assessment and the emergency procedure.
   - Flags: no safety data sheet, safety data sheet review due, no risk
     assessment, no emergency procedure, exposure monitoring due.
   The hazard classification and controls come from the supplier's safety
   data sheet; the system does not classify substances itself.
   ========================================================================== */
'use strict';

const canHCS = () => can('hcs.manage');
const GHS = ['Explosive', 'Flammable', 'Oxidising', 'Gas under pressure', 'Corrosive', 'Acute toxicity', 'Harmful / irritant', 'Health hazard', 'Hazardous to the environment'];
const subs = () => (S.substances || []).filter(x => x.org === S.ui.org && inSite(x, S.ui.site));
const sdsDoc = x => x.sdsDoc && byId('documents', x.sdsDoc);
const hasSds = x => !!(sdsDoc(x) || x.sdsFile);
const sdsDue = x => hasSds(x) && x.sdsReview && daysTo(x.sdsReview) < 0;
const monDue = x => x.monitoring && x.monitoring.next && daysTo(x.monitoring.next) < 0;
function subFlags(x) { if (x.status === 'Discontinued') return []; const f = []; if (!hasSds(x)) f.push('No safety data sheet'); if (sdsDue(x)) f.push('SDS review due'); if (!x.ra) f.push('No risk assessment'); if (!x.emergency) f.push('No emergency procedure'); if (monDue(x)) f.push('Exposure monitoring due'); return f; }
const SUB_F = {
  fsite: { all: 'All branches', list: () => orgSites().length > 1 ? branchOpts() : [], test: (x, v) => x.site === v },
  fclass: { all: 'All hazard classes', list: () => GHS.map(g => ({ value: g, label: g })), test: (x, v) => (x.ghs || []).includes(v) },
  fflag: { all: 'Anything', list: () => ['No safety data sheet', 'SDS review due', 'No risk assessment', 'No emergency procedure', 'Exposure monitoring due'].map(s => ({ value: s, label: s })).concat([{ value: 'any', label: 'Any gap' }]), test: (x, v) => v === 'any' ? subFlags(x).length > 0 : subFlags(x).includes(v) },
  fstatus: { all: 'In use', list: () => [{ value: 'Discontinued', label: 'Discontinued' }], test: (x, v) => x.status === v }
};
ROUTES.substances = (p, q = {}) => {
  if (p[0] && /^HCS-/.test(p[0])) return subDetail(p[0]);
  const all = subs(), inUse = all.filter(x => x.status !== 'Discontinued'), rows = regFilter(q.fstatus ? all : inUse, q, SUB_F);
  const html = `${pageHead('Hazardous substances', 'Every hazardous chemical substance used or stored, with its safety data sheet, controls, PPE, risk assessment and emergency procedure. Classification and controls come from the supplier\'s safety data sheet.', '', scopePill())}${canHCS() ? fabBtn('subNew', 'Add substance') : ''}
    <div class="kpis">${kpi('Substances in use', inUse.length, `${new Set(inUse.map(x => x.location)).size} storage location(s)`, 'blue', '#/substances', 'flask')}
      ${kpi('Without a safety data sheet', inUse.filter(x => !hasSds(x)).length, `${inUse.filter(sdsDue).length} SDS review(s) due`, inUse.some(x => !hasSds(x)) ? 'red' : inUse.some(sdsDue) ? 'amber' : 'green', '#/substances?fflag=No%20safety%20data%20sheet', 'docs')}
      ${kpi('Without a risk assessment', inUse.filter(x => !x.ra).length, 'Link the assessment', inUse.some(x => !x.ra) ? 'amber' : 'green', '#/substances?fflag=No%20risk%20assessment', 'risk')}
      ${kpi('Exposure monitoring due', inUse.filter(monDue).length, `${inUse.filter(x => !x.emergency).length} without an emergency procedure`, inUse.some(monDue) ? 'amber' : 'green', '#/substances?fflag=Exposure%20monitoring%20due', 'clock')}</div>
    <div class="card"><div class="card-head"><h2>Substance register</h2><span class="ch-sub">Open a substance to see its safety data sheet, controls, monitoring and emergency procedure</span>${canHCS() ? `<button class="btn sm primary" data-act="subNew">${icon('plus', 'sm')} Add substance</button>` : ''}</div>${regFilterBar('#/substances', q, q.fstatus ? all : inUse, rows.length, SUB_F, 'Search substance, supplier, location…')}<div class="card-body flush">${rows.length ? `<div class="table-wrap"><table class="tbl stackable"><thead><tr><th>Substance</th><th>Branch / location</th><th>Hazard classes</th><th>Safety data sheet</th><th>PPE</th><th>Gaps</th></tr></thead><tbody>
      ${rows.map(x => { const d = sdsDoc(x), f = subFlags(x); return `<tr class="rowlink" data-href="#/substances/${x.id}"><td data-label="Substance"><b>${esc(x.name)}</b><div class="t-sub">${esc(x.manufacturer || '')}${x.supplier ? ' · supplier ' + esc(x.supplier) : ''}</div></td><td data-label="Branch">${esc(sname(x.site))}<div class="t-sub">${esc(x.location || '')}${x.quantity ? ' · ' + esc(x.quantity) : ''}</div></td><td data-label="Classes">${(x.ghs || []).map(g => `<span class="tag">${esc(g)}</span>`).join(' ') || '—'}</td><td data-label="SDS">${d ? `<span class="mono">${esc(d.number)}</span>` : x.sdsFile ? esc(x.sdsFile.name) : '<span class="due red">Missing</span>'}${x.sdsReview ? `<div class="t-sub">Review ${fmt(x.sdsReview)}</div>` : ''}</td><td data-label="PPE">${esc((x.ppe || []).join(', ') || '—')}</td><td data-label="Gaps">${f.length ? f.map(t => badge(t, 'amber', true)).join(' ') : badge('Complete', 'green', true)}</td></tr>`; }).join('')}
    </tbody></table></div><div class="mx-legend"><button class="btn sm" data-act="subCsv">${icon('download', 'sm')} Export register (CSV)</button></div>` : emptyList(all.length ? 'No substances match these filters.' : 'No substances recorded yet.')}</div></div>`;
  return { title: 'Hazardous substances', nav: 'substances', crumbs: [['Hazardous Substances', '#/substances']], html };
};
ACT.subCsv = () => csvDownload('Hazardous_substances_register', [['Substance', 'Manufacturer', 'Supplier', 'Branch', 'Location', 'Quantity', 'Hazard classes', 'SDS', 'SDS review', 'PPE', 'Risk assessment', 'Emergency procedure', 'Gaps']].concat(subs().map(x => [x.name, x.manufacturer, x.supplier, sname(x.site), x.location, x.quantity, (x.ghs || []).join('; '), sdsDoc(x) ? sdsDoc(x).number : x.sdsFile ? x.sdsFile.name : 'Missing', x.sdsReview || '', (x.ppe || []).join('; '), x.ra || '', x.emergency ? (byId('documents', x.emergency) || {}).number || x.emergency : '', subFlags(x).join('; ')])));
function subDetail(id) { const x = byId('substances', id); if (!x || x.org !== S.ui.org) return ROUTES.notfound(); const d = sdsDoc(x), ra = x.ra && byId('riskAssessments', x.ra), em = x.emergency && byId('documents', x.emergency), f = subFlags(x);
  const html = `<div class="status-hero"><div><div class="sh-id">${x.id} · ${esc(sname(x.site))} · ${esc(x.location || '')}</div><h1 style="margin:2px 0 6px">${esc(x.name)}</h1><div class="btn-row">${(x.ghs || []).map(g => badge(g, 'orange', true)).join(' ')} ${x.status === 'Discontinued' ? badge('Discontinued', 'grey') : ''}</div></div>
    <div class="sh-actions">${canHCS() ? `<button class="btn" data-act="subEdit" data-id="${x.id}">${icon('edit', 'sm')} Edit</button>${x.monitoring ? `<button class="btn" data-act="subMon" data-id="${x.id}">Record monitoring</button>` : ''}` : ''}</div></div>
  ${f.length ? `<div class="alert warn">${icon('alert')}<div><b>Gaps:</b> ${f.map(esc).join(' · ')}</div></div>` : ''}
  <div class="detail"><div class="stack">
    <div class="card"><div class="card-head"><h2>Safety data sheet</h2></div><div class="card-body">${d ? `<a href="#/documents/${d.id}"><b>${esc(d.number)}</b> ${esc(d.title)}</a>` : x.sdsFile ? `<button type="button" class="link-btn" ${fileAttrs(x.sdsFile)}>${esc(x.sdsFile.name)}</button>` : '<span class="due red">No safety data sheet on file.</span>'}<div class="t-sub mt-s">SDS date ${x.sdsDate ? fmt(x.sdsDate) : '—'} · review by ${x.sdsReview ? dueText(x.sdsReview) : '—'}</div></div></div>
    <div class="card"><div class="card-head"><h2>Controls</h2><span class="ch-sub">From the safety data sheet and risk assessment</span></div><div class="card-body"><div class="kv"><div>Required PPE</div><div>${esc((x.ppe || []).join(', ') || '—')}</div><div>Handling</div><div>${esc(x.handling || '—')}</div><div>Storage</div><div>${esc(x.storage || '—')}</div></div></div></div>
    <div class="card"><div class="card-head"><h2>Exposure monitoring</h2></div><div class="card-body">${x.monitoring ? `<div class="kv"><div>What is monitored</div><div>${esc(x.monitoring.what || '')}</div><div>Last result</div><div>${x.monitoring.last ? fmt(x.monitoring.last) + ' — ' + esc(x.monitoring.result || '') : '—'}</div><div>Next due</div><div>${x.monitoring.next ? dueText(x.monitoring.next) : '—'}</div></div>${(x.monitoring.history || []).length ? `<ul class="timeline mt-s">${x.monitoring.history.slice().reverse().map(h => `<li>${fmt(h.date)} — ${esc(h.result)}${h.file ? ` · <button type="button" class="link-btn" ${fileAttrs(h.file)}>${esc(h.file.name)}</button>` : ''}</li>`).join('')}</ul>` : ''}` : '<p class="muted">No exposure monitoring required (as recorded).</p>'}</div></div>
  </div><div class="stack"><div class="card"><div class="card-head"><h2>Details</h2></div><div class="card-body"><div class="kv">
    <div>Manufacturer</div><div>${esc(x.manufacturer || '—')}</div><div>Supplier</div><div>${esc(x.supplier || '—')}</div><div>Quantity</div><div>${esc(x.quantity || '—')}</div>
    <div>Risk assessment</div><div>${ra ? `<a href="#/risk/${ra.id}">${ra.id} ${esc(ra.title)}</a>` : '<span class="due amber">Not linked</span>'}</div>
    <div>Emergency procedure</div><div>${em ? `<a href="#/documents/${em.id}">${esc(em.number)} ${esc(em.title)}</a>` : '<span class="due amber">Not linked</span>'}</div></div></div></div></div></div>`;
  return { title: x.name, nav: 'substances', crumbs: [['Hazardous Substances', '#/substances'], [x.name, '#']], html }; }
function subForm(x) { const docs = c => S.documents.filter(d => inSite(d, 'ALL') && (!c || c.includes(d.category))).map(d => ({ value: d.id, label: `${d.number} — ${d.title}` }));
  return `<div class="form-grid">${fld({ name: 'name', label: 'Substance (product name)', value: x ? x.name : '', required: true, full: true })}${fld({ name: 'manufacturer', label: 'Manufacturer', value: x ? x.manufacturer || '' : '' })}${fld({ name: 'supplier', label: 'Supplier', value: x ? x.supplier || '' : '' })}
    ${fld({ name: 'site', label: 'Branch', type: 'select', options: siteOptions(x ? x.site : defaultSite(), false), required: true })}${fld({ name: 'location', label: 'Storage location', value: x ? x.location || '' : '', required: true })}${fld({ name: 'quantity', label: 'Typical quantity stored', value: x ? x.quantity || '' : '' })}
    <div class="field full"><label>Hazard classes (from the safety data sheet)</label><div class="chk-row">${GHS.map(g => `<label class="check"><input type="checkbox" name="g_${g.replace(/\W/g, '')}" ${x && (x.ghs || []).includes(g) ? 'checked' : ''}> <span>${g}</span></label>`).join('')}</div></div>
    ${fld({ name: 'sdsDoc', label: 'Safety data sheet (from the Document Manager)', type: 'select', options: opts(docs(['Safety Data Sheet']), x ? x.sdsDoc || '' : '', '— Not in the Document Manager —'), full: true })}${fld({ name: 'sdsFile', label: 'Or upload the safety data sheet', type: 'file', accept: '.pdf', full: true })}
    ${fld({ name: 'sdsDate', label: 'SDS date', type: 'date', value: x ? x.sdsDate || '' : '' })}${fld({ name: 'sdsReview', label: 'Check for a newer SDS by', type: 'date', value: x ? x.sdsReview || '' : addMonths(TODAY, 36) })}
    ${fld({ name: 'ppe', label: 'Required PPE (comma separated)', value: x ? (x.ppe || []).join(', ') : '', full: true })}${fld({ name: 'handling', label: 'Handling controls', type: 'textarea', rows: 2, value: x ? x.handling || '' : '', full: true })}${fld({ name: 'storage', label: 'Storage controls', type: 'textarea', rows: 2, value: x ? x.storage || '' : '', full: true })}
    ${fld({ name: 'ra', label: 'Risk assessment', type: 'select', options: opts((S.riskAssessments || []).filter(a => a.org === S.ui.org && a.status !== 'Superseded').map(a => ({ value: a.id, label: `${a.id} — ${a.title}` })), x ? x.ra || '' : '', '— Not linked —') })}
    ${fld({ name: 'emergency', label: 'Emergency procedure', type: 'select', options: opts(docs(['Emergency Plan', 'Procedure', 'Safe Work Procedure']), x ? x.emergency || '' : '', '— Not linked —') })}
    ${fld({ name: 'monWhat', label: 'Exposure monitoring (if required — what is monitored)', value: x && x.monitoring ? x.monitoring.what : '', full: true })}${fld({ name: 'monNext', label: 'Next monitoring due', type: 'date', value: x && x.monitoring ? x.monitoring.next || '' : '' })}
    ${fld({ name: 'status', label: 'Status', type: 'select', options: opts(['In use', 'Discontinued'], x && x.status === 'Discontinued' ? 'Discontinued' : 'In use') })}</div>`; }
function subRead(m, x) { const v = readForm(m); const o = { name: v.name, manufacturer: v.manufacturer, supplier: v.supplier, site: v.site, location: v.location, quantity: v.quantity, ghs: GHS.filter(g => m.querySelector(`[name=g_${g.replace(/\W/g, '')}]`).checked), sdsDoc: v.sdsDoc || null, sdsDate: v.sdsDate, sdsReview: v.sdsReview, ppe: v.ppe.split(',').map(s => s.trim()).filter(Boolean), handling: v.handling, storage: v.storage, ra: v.ra || null, emergency: v.emergency || null, status: v.status === 'Discontinued' ? 'Discontinued' : 'Active' };
  if (v.sdsFile) o.sdsFile = v.sdsFile; o.monitoring = v.monWhat ? Object.assign((x && x.monitoring) || { history: [] }, { what: v.monWhat, next: v.monNext }) : null; return o; }
ACT.subNew = () => openModal({ title: 'Add a hazardous substance', size: 'wide', body: subForm(null), buttons: [{ label: 'Add', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; S.substances = S.substances || []; const x = Object.assign({ id: nextId('HCS-', 'substances'), org: S.ui.org }, subRead(m, null)); x.org = siteOrgOf(x.site); S.substances.push(x); log(`Added hazardous substance ${x.name}`, '#/substances/' + x.id); save(); navigate('#/substances/' + x.id); } }] });
ACT.subEdit = (el) => { const x = byId('substances', el.dataset.id); openModal({ title: `Edit ${x.name}`, size: 'wide', body: subForm(x), buttons: [{ label: 'Save', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; Object.assign(x, subRead(m, x)); log(`Updated hazardous substance ${x.name}`, '#/substances/' + x.id); save(); rerender(); } }] }); };
ACT.subMon = (el) => { const x = byId('substances', el.dataset.id); openModal({ title: 'Record exposure monitoring', sub: x.name, body: `<div class="form-grid">${fld({ name: 'date', label: 'Date', type: 'date', value: TODAY, required: true })}${fld({ name: 'result', label: 'Result', required: true, full: true })}${fld({ name: 'file', label: 'Report', type: 'file', full: true })}${fld({ name: 'next', label: 'Next monitoring due', type: 'date', value: addMonths(TODAY, 12), required: true })}</div>`,
  buttons: [{ label: 'Save', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; const v = readForm(m); x.monitoring.history = x.monitoring.history || []; x.monitoring.history.push({ date: v.date, result: v.result, file: v.file, by: S.ui.user }); Object.assign(x.monitoring, { last: v.date, result: v.result, next: v.next }); log(`Recorded exposure monitoring for ${x.name}`, '#/substances/' + x.id); save(); rerender(); } }] }); };

/* ---------------- Wiring + demo data ---------------- */
(() => { const g = NAV.find(x => x.group === 'Operational safety'); if (g && !g.items.some(i => i[0] === 'substances')) g.items.push(['substances', 'Hazardous Substances', 'flask']); })();
AREA_OF.substances = 'area.substances'; if (!TOP_ROUTES.includes('substances')) TOP_ROUTES.push('substances');
const _myTasksBeforeHCS = myTasks;
myTasks = function () { const out = _myTasksBeforeHCS(); if (canHCS()) { const g = subs().filter(x => subFlags(x).length); if (g.length) out.push({ title: `${g.length} hazardous substance(s) with gaps`, sub: [...new Set(g.flatMap(subFlags))].join(', '), link: '#/substances?fflag=any', sev: g.some(x => !hasSds(x)) ? 'red' : 'amber' }); } return out; };
MIGRATIONS.push(() => {
  if (S.migr && S.migr.hcs) return; S.migr = S.migr || {}; S.migr.hcs = true;
  addArea('area.substances', 'Hazardous substances', 'area.ppe', 'area.assets');
  addPerm('hcs.manage', 'Manage the hazardous substances register', ['HSEQ Manager', 'Safety Consultant', 'Branch Manager']);
  S.substances = S.substances || [];
  const X = (id, o) => { if (!byId('substances', id)) S.substances.push(Object.assign({ id, org: 'ORG-1', status: 'Active', ghs: [], ppe: [] }, o)); };
  X('HCS-001', { name: 'Solvex 300 Degreaser', manufacturer: 'Demo Chemicals (fictional)', supplier: 'Demo Supplies', site: 'S-DBN', location: 'Workshop degreasing bay', quantity: '2 × 25 L', ghs: ['Flammable', 'Harmful / irritant', 'Hazardous to the environment'], sdsDoc: 'DOC-018', sdsDate: addDays(TODAY, -900), sdsReview: addDays(TODAY, -30), ppe: ['Chemical-resistant gloves', 'Safety glasses'], handling: 'Use only in the ventilated degreasing bay; keep containers closed.', storage: 'Flammables cabinet; away from ignition sources.', ra: 'RA-002', emergency: 'DOC-024', monitoring: { what: 'Solvent vapour in the degreasing bay', last: addDays(TODAY, -380), result: 'Below the limit used by the occupational hygienist', next: addDays(TODAY, -15), history: [{ date: addDays(TODAY, -380), result: 'Below the limit used by the occupational hygienist', by: 'P-002' }] } });
  X('HCS-002', { name: 'Hydraulic Oil ISO VG 46', manufacturer: 'Demo Lubricants (fictional)', supplier: 'Demo Supplies', site: 'S-JHB', location: 'Workshop oil store', quantity: '4 × 20 L', ghs: [], sdsDoc: 'DOC-019', sdsDate: addDays(TODAY, -400), sdsReview: addDays(TODAY, 700), ppe: ['Nitrile gloves'], handling: 'Avoid prolonged skin contact.', storage: 'Bunded oil store.', ra: null, emergency: 'DOC-008', monitoring: null });
  X('HCS-003', { name: 'Aerosol Spray Paint (Industrial Enamel)', manufacturer: 'Demo Paints (fictional)', supplier: 'Demo Supplies', site: 'S-CPT', location: 'Paint store', quantity: '24 cans', ghs: ['Flammable', 'Gas under pressure'], sdsDoc: 'DOC-020', sdsDate: addDays(TODAY, -300), sdsReview: addDays(TODAY, 800), ppe: ['Respirator', 'Safety glasses'], handling: 'Spray only in ventilated areas.', storage: 'Below 50 °C, away from heat.', ra: null, emergency: null, monitoring: null });
  X('HCS-004', { name: 'Battery acid (sulphuric acid electrolyte)', manufacturer: '', supplier: 'Battery supplier (demo)', site: 'S-JHB', location: 'Battery charging bay', quantity: 'In forklift batteries', ghs: ['Corrosive'], sdsDoc: null, sdsDate: '', sdsReview: '', ppe: ['Face shield', 'Acid-resistant gloves', 'Apron'], handling: 'Top up with distilled water only, wearing PPE.', storage: 'In the batteries; spill kit at the bay.', ra: 'RA-001', emergency: 'DOC-008', monitoring: null });
});
